#include <stdio.h>

#define MAXF 8

int fifo_faults(const int *r, int n, int m) {
    int q[MAXF], head = 0, f = 0, faults = 0;
    for (int i = 0; i < n; i++) {
        int hit = 0;
        for (int j = 0; j < f; j++) if (q[j] == r[i]) { hit = 1; break; }
        if (hit) continue;
        faults++;
        if (f < m) { q[f++] = r[i]; }
        else { q[head] = r[i]; head = (head + 1) % m; }
    }
    return faults;
}

int lru_faults(const int *r, int n, int m) {
    int q[MAXF], last[MAXF], f = 0, faults = 0;
    for (int i = 0; i < n; i++) {
        int hit = -1;
        for (int j = 0; j < f; j++) if (q[j] == r[i]) { hit = j; break; }
        if (hit >= 0) { last[hit] = i; continue; }
        faults++;
        if (f < m) { q[f] = r[i]; last[f] = i; f++; }
        else {
            int v = 0;
            for (int j = 1; j < m; j++) if (last[j] < last[v]) v = j;
            q[v] = r[i]; last[v] = i;
        }
    }
    return faults;
}

int main(void) {
    int ref[] = {1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5};
    int n = 12;
    printf("reference string = 1,2,3,4,1,2,5,1,2,3,4,5\n");
    printf("=== FIFO ===\n");
    for (int m = 3; m <= 4; m++) printf("  frames=%d  faults=%d\n", m, fifo_faults(ref, n, m));
    printf("  more frames -> MORE faults => BELADY ANOMALY\n");
    printf("=== LRU (stack algorithm) ===\n");
    for (int m = 3; m <= 4; m++) printf("  frames=%d  faults=%d\n", m, lru_faults(ref, n, m));
    printf("  more frames -> faults never increase (monotone non-increasing)\n");
    return 0;
}
